public static double Canberra(double[] p, double[] q) {
        double distance = 0;

        for (int i = 0; i < p.length; i++) {
            distance += Math.abs(p[i] - q[i]) / (Math.abs(p[i]) + Math.abs(q[i]));
        }

        return distance;
    }

