code:
public static double Chebyshev(double[] p, double[] q) {
        double max = Math.abs(p[0] - q[0]);

        for (int i = 1; i < p.length; i++) {
            double abs = Math.abs(p[i] - q[i]);
            if (abs > max) max = abs;
        }

        return max;
    }

