code:
public static double Minkowski(double[] u, double[] v, double p) {
        double distance = 0;
        for (int i = 0; i < u.length; i++) {
            distance += Math.pow(Math.abs(u[i] - v[i]), p);
        }
        return Math.pow(distance, 1 / p);
    }

