code:
public Object get(int dataSet) throws SerializationException {
		Object result = null;
		for (Iterator<DataSet> i = dataSets.iterator(); i.hasNext();) {
			DataSet ds = i.next();
			DataSetInfo info = ds.getInfo();
			if (info.getDataSetNumber() == dataSet) {
				result = getData(ds);
				break;
			}
		}
		return result;
	}

