public void writeTo(IIMWriter writer) throws IOException {
		final boolean doLog = log != null;
		for (Iterator<DataSet> i = dataSets.iterator(); i.hasNext();) {
			DataSet ds = i.next();
			writer.write(ds);
			if (doLog) {
				log.debug("Wrote data set " + ds);
			}
		}
	}

