code:
public static void Shuffle(double[] array, long seed) {
        Random random = new Random();
        if (seed != 0) random.setSeed(seed);

        for (int i = array.length - 1; i > 0; i--) {
            int index = random.nextInt(i + 1);
            double temp = array[index];
            array[index] = array[i];
            array[i] = temp;
        }
    }

