code:
synchronized void writeAddInfo(ByteArrayOutputStream os)
	{
		os.write(getAddInfoLength());
		for (int i = 0; i < addInfo.length; i++)
			if (addInfo[i] != null) {
				os.write(i);
				os.write(addInfo[i].length);
				os.write(addInfo[i], 0, addInfo[i].length);
			}
	}

