public synchronized CEMILData getFrame()
	{
		final CEMILData[] c = (CEMILData[]) value;
		final int first = first();
		final CEMILData f = c[first];
		if (size > 0 && consuming) {
			--size;
			c[first] = null;
			timestamps[first] = 0;
			if (size == 0)
				next = 0;
		}
		return f;
	}

