public static boolean isSuccess(JsonRtn jsonRtn) {
        if (jsonRtn == null) {
            return false;
        }

        String errCode = jsonRtn.getErrCode();
        if (StringUtils.isEmpty(errCode) || StringUtils.equals(WECHAT_JSON_RTN_SUCCESS_CODE, errCode)) {
            return true;
        }

        return false;
    }

