code:
public KNXNetworkLink detach()
	{
		final KNXNetworkLink lnk = tl.detach();
		if (lnk != null) {
			logger.info("detached from " + lnk.getName());
			LogManager.getManager().removeLogService(logger.getName());
		}
		detached = true;
		return lnk;
	}

