			+ ((String[]) config.get(1))[2]);
		final String padding = "                                   ";
		for (int i = 2; i < config.size(); ++i) {
			final String[] s = (String[]) config.get(i);
			System.out.println(s[1] + padding.substring(s[1].length()) + s[2]);
		}
	}

