code:
public static String decode(byte[] tpdu, KNXAddress dst)
	{
		if (tpdu.length < 1)
			throw new KNXIllegalArgumentException("TPDU length too short");
		final String s = decodeTPCI(tpdu[0] & 0xff, dst);
		if (tpdu.length > 1)
			return s + ", " + decodeAPCI(getAPDUService(tpdu));
		return s;
	}

