code:
byte[] toByteArray(ByteArrayOutputStream os)
	{
		byte[] buf = device.toByteArray();
		os.write(buf, 0, buf.length);
		buf = suppfam.toByteArray();
		os.write(buf, 0, buf.length);
		if (mfr != null) {
			buf = mfr.toByteArray();
			os.write(buf, 0, buf.length);
		}
		return os.toByteArray();
	}

