code:
byte[] toByteArray(ByteArrayOutputStream os)
	{
		os.write(channelid);
		os.write(status);
		if (endpt != null && crd != null) {
			byte[] buf = endpt.toByteArray();
			os.write(buf, 0, buf.length);
			buf = crd.toByteArray();
			os.write(buf, 0, buf.length);
		}
		return os.toByteArray();
	}

