private float max(float x, float y, float z) {
        if (x > y) {
            // not y
            if (x > z) {
                return x;
            }
            else {
                return z;
            }
        }
        else {
            // not x
            if (y > z) {
                return y;
            }
            else {
                return z;
            }
        }
    }

