@Override
    public IntDoubleVector getGradient(IntDoubleVector params) {
        IntDoubleDenseVector gradient = new IntDoubleDenseVector(numParams);
        for (int j=0; j<numParams; j++) {
            gradient.set(j, - params.get(j) * lambda);
        }
        return gradient;
    }

