@Override
    public void show() {
	boolean fireOpen = !isShowing();
	super.show();

	// adjust the size of the glass
	if (isShowing()) {
	    adjustGlassSize();
	}

	// fire the open event
	if (fireOpen) {
	    OpenEvent.fire(this, this);
	}
    }

