public static Bounds getSymmetricBounds(int dim, double l, double u) {
        double [] L = new double[dim];
        double [] U = new double[dim];
        for(int i=0; i<dim; i++) {
            L[i] = l;
            U[i] = u;
        }
        return new Bounds(L, U);
    }

