code:
private String parseJavaId() {
		StringBuilder sb = new StringBuilder();
		int ch;
		while (true) {
			ch = characterBuffer.peekChar();
			if (ch == CharacterBuffer.EOS || !isJavaIdentifierPart(ch)) {
				if (sb.length() == 0) {
					return null;
				}
				return sb.toString();
			}
			sb.append((char) ch);
			characterBuffer.nextChar();
		}
	}

