code:
public void addCancelListener(final CancelListener<T> listener) {
		final Object v = this.value.get();
		if (v == null) {
			this.listeners.add(listener);
		} else if (FutureImpl.CANCELLED_FLAG.equals(v)) {
			listener.wasCancelled(this.getId());
		}
	}

