code:
public static @NotNull String urlEncode(@Nullable String value) {
    if (value == null) {
      return "";
    }
    try {
      return URLEncoder.encode(value, CharEncoding.UTF_8);
    }
    catch (UnsupportedEncodingException ex) {
      throw new RuntimeException(ex);
    }
  }

