public static <T extends CObject> T get(Object obj, String path) {
        T result = find(obj, RmPath.valueOf(path).segments());
        if (result == null) {
            throw new AmObjectNotFoundException("Object " + obj + " has no child on path " + path);
        }
        return result;
    }

