            throw new PopbillException(-99999999, "세금계산서 정보가 입력되지 않았습니다.");

        String PostData = toJsonString(taxinvoice);

        return httppost("/Taxinvoice/" + KeyType.name() + "/" + MgtKey,
                CorpNum, PostData, UserID, "PATCH", Response.class);
    }

