code:
public Object visit(And filter, Object userData) {
		Criterion c = null;
		for (Filter element : filter.getChildren()) {
			if (c == null) {
				c = (Criterion) element.accept(this, userData);
			} else {
				c = Restrictions.and(c, (Criterion) element.accept(this, userData));
			}
		}
		return c;
	}

