code:
private String fixSpecials(final String inString) {
		StringBuilder tmp = new StringBuilder();

		for (int i = 0; i < inString.length(); i++) {
			char chr = inString.charAt(i);

			if (isSpecial(chr)) {
				tmp.append(this.escape);
				tmp.append(chr);
			} else {
				tmp.append(chr);
			}
		}

		return tmp.toString();
	}

