code:
protected void appendWhereClause(StringBuffer where, Criteria crit, StringBuffer stmt)
    {
        if (where.length() == 0)
        {
            where = null;
        }

        if (where != null || (crit != null && !crit.isEmpty()))
        {
            stmt.append(" WHERE ");
            appendClause(where, crit, stmt);
        }
    }

